# Symmetric search: independent sets in Cay(F_p^3, S) (S = ±{(a^2,2ab,b^2)}) that are unions of orbits of the group
# H generated by (x,y,z) -> (t^2 x, y, t^-2 z) [congruence by diag(t,1/t)] and (x,y,z) -> (l x, l y, l z), l a square.
# Exact max-weight independent set on the orbit graph by branch and bound.
import sys,itertools,time
p=int(sys.argv[1]); secs=float(sys.argv[2]); dt=int(sys.argv[3]); dl=int(sys.argv[4]); extra=sys.argv[5] if len(sys.argv)>5 else ''
sq=sorted({(x*x)%p for x in range(1,p)})
S=set()
for a in range(p):
    for b in range(p):
        if a or b:
            s=((a*a)%p,(2*a*b)%p,(b*b)%p); S.add(s); S.add(tuple((-c)%p for c in s))
inv=lambda t: pow(t,p-2,p)
gens=[]
def subgroup(order):
    return [x for x in range(1,p) if pow(x,order,p)==1]
for t2 in subgroup(dt):
    if t2 not in sq: continue
    ti2=inv(t2); gens.append(lambda v,t2=t2,ti2=ti2:((t2*v[0])%p,v[1],(ti2*v[2])%p))
for l in subgroup(dl):
    if l not in sq: continue
    gens.append(lambda v,l=l:((l*v[0])%p,(l*v[1])%p,(l*v[2])%p))
if 'swap' in extra: gens.append(lambda v:(v[2],v[1],v[0]))
if 'flip' in extra: gens.append(lambda v:(v[0],(-v[1])%p,v[2]))
pts=list(itertools.product(range(p),repeat=3)); orb={}; orbits=[]
for v in pts:
    if v in orb: continue
    O={v}; fr=[v]
    while fr:
        u=fr.pop()
        for g in gens:
            w=g(u)
            if w not in O: O.add(w); fr.append(w)
    for u in O: orb[u]=len(orbits)
    orbits.append(sorted(O))
def internal_ok(O):
    s=set(O)
    return not any(tuple((a-b)%p for a,b in zip(u,v)) in S for u in O for v in O if u!=v)
K=len(orbits)
ok=[internal_ok(O) for O in orbits]
adjo=[0]*K
for i,O in enumerate(orbits):
    if not ok[i]: continue
    for u in O:
        for s in S:
            w=tuple((a+b)%p for a,b in zip(u,s)); j=orb[w]
            if j!=i: adjo[i]|=1<<j
wt=[len(O) for O in orbits]
cand0=sum(1<<i for i in range(K) if ok[i])
best=[0,0]; t0=time.time()
order=sorted(range(K),key=lambda i:-wt[i])
def rec(cand,cur,val):
    if time.time()-t0>secs: return
    if val>best[0]: best[0]=val; best[1]=cur
    if not cand: return
    if val+sum(wt[i] for i in range(K) if cand>>i&1)<=best[0]: return
    i=max((j for j in range(K) if cand>>j&1),key=lambda j:wt[j])
    rec(cand&~(1<<i)&~adjo[i],cur|(1<<i),val+wt[i])
    rec(cand&~(1<<i),cur,val)
rec(cand0,0,0)
print('p',p,'orbits',K,'internally independent',sum(ok),'best union size',best[0],'q^2',p*p,'time',round(time.time()-t0,1),'complete' if time.time()-t0<secs else 'TIMEOUT(best so far)')
print('orbit sizes used',sorted(wt[i] for i in range(K) if best[1]>>i&1))
